5. 简易计算器

先输入一个运算符（+ - * / 之一），再输入两个整数，输出运算结果；运算符不是这四个字符时输出 运算符错误。题目保证输入不会出现除 0。

本题推荐最大时长：15分钟

题目输入案例：* 4 5

输出结果案例：20

答案

C

#include <stdio.h>
int main(){
	char op;						// 运算符
	int a, b;					// 两个数字
	scanf(" %c %d %d",&op,&a,&b);	// %c 前面的空格：跳过输入里残留的换行
	switch (op) {
		case '+':
			printf("%d\n", a + b);
			break;
		case '-':
			printf("%d\n", a - b);
			break;
		case '*':
			printf("%d\n", a * b);
			break;
		case '/':
			printf("%d\n", a / b);	// 整数除法，题目保证 b 不为 0
			break;
		default:
			printf("运算符错误\n");
	}
	return 0;
}

C++

#include <iostream>
int main(){
	char op;						// 运算符
	int a, b;					// 两个数字
	std::cin >> op >> a >> b;		// C++ 不需要 C 那样的空格技巧
	switch (op) {
		case '+':
			std::cout << a + b << "\n";
			break;
		case '-':
			std::cout << a - b << "\n";
			break;
		case '*':
			std::cout << a * b << "\n";
			break;
		case '/':
			std::cout << a / b << "\n";	// 整数除法，题目保证 b 不为 0
			break;
		default:
			std::cout << "运算符错误\n";
	}
	return 0;
}
